package com.example.billingservice.controller;
import com.example.billingservice.model.*;
import com.example.billingservice.service.BillingService;
import io.swagger.v3.oas.annotations.*;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/subscriptions")
@Tag(name="Billing")public class BillingController{private final BillingService service;public BillingController(BillingService service){this.service=service;}@PostMapping @Operation(summary="Create or return a subscription awaiting dependencies")public ResponseEntity<Subscription>create(@Valid@RequestBody CreateSubscriptionRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(request));}@GetMapping @Operation(summary="List subscriptions, find one by order, or list a customer's subscriptions (optionally by status)")public Object list(@RequestParam(required=false)String orderId,@RequestParam(required=false)String customerId,@RequestParam(required=false)BillingStatus status){if(orderId!=null)return service.byOrder(orderId);if(customerId!=null)return service.byCustomer(customerId,status);return service.list();}@PostMapping("/{orderId}/approve")@Operation(summary="Start recurring billing",description="Moves READY_FOR_BILLING to ACTIVE only when payment is COMPLETED, activation is ACTIVE and delivery is DELIVERED; sets nextBillingAt for invoicing.")public Subscription approve(@PathVariable String orderId,@Valid@RequestBody(required=false)BillingDecisionRequest request){return service.approve(orderId,request==null?null:request.reason());}@PostMapping("/{orderId}/reject")@Operation(summary="Reject billing before it starts",description="A reason is required.")public Subscription reject(@PathVariable String orderId,@Valid@RequestBody BillingDecisionRequest request){return service.reject(orderId,request.reason());}@GetMapping("/due")@Operation(summary="ACTIVE subscriptions due for invoicing on or before a date",description="Paged in a stable order; used by the invoicing batch.")public java.util.List<Subscription>due(@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE)java.time.LocalDate asOf,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="200")int size){return service.due(asOf,page,size);}@PutMapping("/{orderId}/billing-day")@Operation(summary="Change the day of the month the subscription is invoiced on (1-28)")public Subscription billingDay(@PathVariable String orderId,@Valid@RequestBody BillingDayRequest request){return service.changeBillingDay(orderId,request.billingDay());}@PostMapping("/{orderId}/billing-periods")@Operation(summary="Record an invoiced billing period",description="Moves the next billing date from periodStart to periodEnd. Idempotent.")public Subscription billed(@PathVariable String orderId,@Valid@RequestBody BillingPeriodRequest request){return service.recordBilledPeriod(orderId,request.periodStart(),request.periodEnd());}@PostMapping("/{orderId}/suspend")@Operation(summary="Suspend recurring billing")public Subscription suspend(@PathVariable String orderId){return service.suspend(orderId);}@PostMapping("/{orderId}/cancel")@Operation(summary="Cancel recurring billing idempotently")public Subscription cancel(@PathVariable String orderId){return service.cancel(orderId);}}
